<?php
namespace App\Services\Notification;use App\Models\Clinic;use App\Models\ClinicNotificationSetting;use App\Models\Notification;use App\Models\User;use App\Services\Sms\SmsGatewayManager;use Illuminate\Support\Facades\Log;
class ClinicNotificationDispatcher{public function __construct(private SmsGatewayManager $sms){}
 private function render(?string $template,array $data,string $fallback){return preg_replace_callback('/\{([a-zA-Z0-9_]+)\}/',fn($m)=>$data[$m[1]]??$m[0],$template?:$fallback);}
 public function send(?int $clinicId,string $event,User $user,array $data=[],string $title='اعلان دکتر وب',string $body='رویداد جدیدی ثبت شد'):void{$setting=$clinicId?ClinicNotificationSetting::where(['clinic_id'=>$clinicId,'event_key'=>$event])->first():null;$panel=$setting?->panel_enabled??true;$sms=$setting?->sms_enabled??false;$title=$this->render($setting?->panel_title,$data,$title);$body=$this->render($setting?->panel_template,$data,$body);if($panel)Notification::create(['tenant_id'=>$user->tenant_id,'user_id'=>$user->id,'type'=>$event,'title'=>$title,'body'=>$body,'data'=>$data,'sent_at'=>now()]);$phone=$user->mobile??$user->phone;if($sms&&$phone){try{$this->sms->sendWithFallback($phone,$this->render($setting?->sms_template,$data,$body));}catch(\Throwable $e){Log::error('Clinic SMS failed',['event'=>$event,'error'=>$e->getMessage()]);}}}}
